#!/bin/sh
# Writes what the packages install under share/: the shell completion scripts and the man pages of the tools, laid
# out like the share/ tree of a package. The completion scripts and the man1 pages are generated by the tools
# themselves; the man8 pages are the hand-written ones in packaging/man. Nothing generated is committed: the
# packages and the release archives run this at build time.
#
#   scripts/gen-share.sh OUTDIR [BINDIR]
#
# OUTDIR gets, for jailops, jailops-sync and jailops-backupd:
#   bash-completion/completions/<tool>
#   zsh/site-functions/_<tool>
#   fish/vendor_completions.d/<tool>.fish
#   man/man1/<tool>*.1          (jailops and jailops-sync: one page per command)
#   man/man8/<tool>.8           (jailopsd, jailops-priv, jailops-backupd)
# The tools are taken from BINDIR (with or without a -<os>-<arch> suffix; they must run on this machine), or built and
# run from source with `go run` when BINDIR is not given. Set SOURCE_DATE_EPOCH for a reproducible date in the pages.
set -eu

[ $# -ge 1 ] || { sed -n '2,16p' "$0" | sed 's/^# \{0,1\}//'; exit 2; }
out=$1; bindir=${2:-}
here=$(cd "$(dirname "$0")/.." && pwd)

run() { # run TOOL ARGS...: the tool from BINDIR, else from source
	tool=$1; shift
	if [ -n "$bindir" ]; then
		for f in "$bindir/$tool" "$bindir/$tool"-freebsd-* "$bindir/$tool"-linux-* "$bindir/$tool"-darwin-*; do
			[ -x "$f" ] && { "$f" "$@"; return; }
		done
		echo "$tool not found in $bindir" >&2; exit 1
	fi
	(cd "$here" && CGO_ENABLED=0 go run "./cmd/$tool" "$@")
}

mkdir -p "$out/bash-completion/completions" "$out/zsh/site-functions" "$out/fish/vendor_completions.d" "$out/man/man1" "$out/man/man8"
for tool in jailops jailops-sync jailops-backupd; do
	run "$tool" completion bash > "$out/bash-completion/completions/$tool"
	run "$tool" completion zsh > "$out/zsh/site-functions/_$tool"
	run "$tool" completion fish > "$out/fish/vendor_completions.d/$tool.fish"
done
for tool in jailops jailops-sync; do
	run "$tool" man "$out/man/man1"
done
cp "$here"/packaging/man/*.8 "$out/man/man8/"
find "$out" -type f -exec chmod 644 {} +
echo "completion scripts and man pages in $out"
